        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Looks tired but not distressed; good eye contact; tearful when discussing work; no psychotic features; oriented."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-13",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-13",
        "status": "final",
        "code": {
          "text": "Left breast symptoms"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Reports left breast lumpiness. No pain now; mild cyclical tenderness only. No nipple discharge or skin change. Patient is very anxious about cancer."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-14",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-14",
        "status": "final",
        "code": {
          "text": "Left breast ultrasound"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "1.2 cm simple cyst at 2 o’clock, oval and anechoic, with thin wall and posterior enhancement; no solid components or abnormal nodes. BI-RADS 2, benign cyst; no further imaging required."
      }
    },
