      "fullUrl": "https://example.org/fhir/Observation/observation-15",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-15",
        "status": "final",
        "code": {
          "text": "Alcohol and other substance use"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "No excess alcohol reported; 1–2 glasses of wine on Friday and Saturday. No other substances reported."
      }
    },
