      "resource": {
        "resourceType": "Observation",
        "id": "observation-16",
        "status": "final",
        "code": {
          "text": "Sertraline tolerability at phone check"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Patient had started sertraline that morning and reported mild nausea only; no suicidal ideation."
